def remove_duplicates_keep_order(nums):
    result = []
    for x in nums:
        if x not in result:
            result.append(x)
    return result

def count_subsets_with_sum(nums, target):
    n = len(nums)
    count = 0
    for mask in range(1 << n):
        total = 0
        for i in range(n):
            if (mask >> i) & 1:
                total += nums[i]
        if total == target:
            count += 1
    return count

def shortest_palindrome(s):
    n = len(s)
    for i in range(n, -1, -1):
        prefix = s[:i]
        if prefix == prefix[::-1]:
            return s[i:][::-1] + s
    return s

def trailing_zeroes(n):
    if n < 5:
        return 0
    quotient = n // 5
    return quotient + trailing_zeroes(quotient)

def count_pairs_below_target(nums, target):
    arr = sorted(nums)
    left, right = 0, len(arr) - 1
    count = 0
    while left < right:
        if arr[left] + arr[right] < target:
            count += right - left
            left += 1
        else:
            right -= 1
    return count

