string reverseWords(const string& s) {
    string result;
    int i = (int)s.size() - 1;
    while (i >= 0) {
        while (i >= 0 && s[i] == ' ') i--;
        if (i < 0) break;
        int j = i;
        while (j >= 0 && s[j] != ' ') j--;
        if (!result.empty()) result += ' ';
        result += s.substr(j + 1, i - j);
        i = j;
    }
    return result;
}

