long long triangleNumber(const vector<int>& nums) {
    vector<int> a(nums.begin(), nums.end());
    sort(a.begin(), a.end());
    int n = a.size();
    long long count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            long long limit = (long long)a[i] + a[j];
            int k = lower_bound(a.begin() + j + 1, a.end(), limit) - a.begin();
            count += k - (j + 1);
        }
    }
    return count;
}

