function runLengthEncode(s) {
    let encoded = "";
    let i = 0;
    while (i < s.length) {
        let j = i;
        while (j < s.length && s[j] === s[i]) {
            j++;
        }
        encoded += s[i] + (j - i);
        i = j;
    }
    return encoded;
}

function maxWindowSum(nums, k) {
    if (k <= 0 || k > nums.length) return 0;
    let windowSum = 0;
    for (let i = 0; i < k; i++) {
        windowSum += nums[i];
    }
    let best = windowSum;
    for (let i = k; i < nums.length; i++) {
        windowSum += nums[i] - nums[i - k];
        best = Math.max(best, windowSum);
    }
    return best;
}

function countNegatives(grid) {
    const n = grid.length;
    if (n === 0) return 0;
    const m = grid[0].length;
    let col = m;
    let count = 0;
    for (let row = 0; row < n; row++) {
        while (col > 0 && grid[row][col - 1] < 0) {
            col--;
        }
        count += m - col;
    }
    return count;
}

function buildSparseTable(nums) {
    const n = nums.length;
    const table = [nums.slice()];
    for (let len = 2; len <= n; len *= 2) {
        const prev = table[table.length - 1];
        const half = len / 2;
        const row = [];
        for (let i = 0; i + len <= n; i++) {
            row.push(Math.min(prev[i], prev[i + half]));
        }
        table.push(row);
    }
    return table;
}

function allSubsequences(s) {
    const result = [""];
    for (const ch of s) {
        const size = result.length;
        for (let i = 0; i < size; i++) {
            result.push(result[i] + ch);
        }
    }
    return result;
}

