func powMod(base, n, mod int) int {
    if n == 0 {
        return 1 % mod
    }
    half := powMod(base, n/2, mod)
    result := half * half % mod
    if n%2 == 1 {
        result = result * (base % mod) % mod
    }
    return result
}

