func countTriplets(arr []int) int {
    n := len(arr)
    prefix := make([]int, n+1)
    for i := 0; i < n; i++ {
        prefix[i+1] = prefix[i] ^ arr[i]
    }
    count := 0
    for i := 0; i < n; i++ {
        for j := i + 1; j < n; j++ {
            for k := j; k < n; k++ {
                if prefix[i]^prefix[j] == prefix[j]^prefix[k+1] {
                    count++
                }
            }
        }
    }
    return count
}

