long long *rangeSums(const int *nums, int n, const int *lefts, const int *rights, int m) {
    long long *prefix = malloc((n + 1) * sizeof(long long));
    long long *answers = malloc(m * sizeof(long long));
    prefix[0] = 0;
    for (int i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }
    for (int q = 0; q < m; q++) {
        answers[q] = prefix[rights[q] + 1] - prefix[lefts[q]];
    }
    free(prefix);
    return answers;
}

