bool containsDuplicate(const int *nums, int n) {
    if (n < 2) {
        return false;
    }
    int *copy = malloc(n * sizeof(int));
    memcpy(copy, nums, n * sizeof(int));
    qsort(copy, n, sizeof(int), compareInts);
    bool found = false;
    for (int i = 1; i < n; i++) {
        if (copy[i] == copy[i - 1]) {
            found = true;
            break;
        }
    }
    free(copy);
    return found;
}

