int **generatePascal(int numRows) {
    const int MOD = 1000000007;
    int **rows = malloc(numRows * sizeof(int *));
    for (int i = 0; i < numRows; i++) {
        rows[i] = malloc((i + 1) * sizeof(int));
        rows[i][0] = 1;
        rows[i][i] = 1;
        for (int j = 1; j < i; j++) {
            rows[i][j] = (rows[i - 1][j - 1] + rows[i - 1][j]) % MOD;
        }
    }
    return rows;
}

from typing import Set


def word_break(s: str, words: Set[str]) -> bool:
    n = len(s)
    can = [False] * (n + 1)
    can[0] = True
    for end in range(1, n + 1):
        for start in range(end):
            piece = s[start:end]
            if can[start] and piece in words:
                can[end] = True
                break
    return can[n]

