def running_medians(nums: List[int]) -> List[float]:
    medians = []
    for i in range(len(nums)):
        window = sorted(nums[:i + 1])
        k = len(window)
        if k % 2 == 1:
            medians.append(float(window[k // 2]))
        else:
            medians.append((window[k // 2 - 1] + window[k // 2]) / 2)
    return medians

