class Solution {
    long long sortCount(vector<int>& a, vector<int>& tmp, int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = lo + (hi - lo) / 2;
        long long count = sortCount(a, tmp, lo, mid) + sortCount(a, tmp, mid, hi);
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) {
            if (a[i] <= a[j]) {
                tmp[k++] = a[i++];
            } else {
                count += mid - i;
                tmp[k++] = a[j++];
            }
        }
        while (i < mid) tmp[k++] = a[i++];
        while (j < hi) tmp[k++] = a[j++];
        for (int t = lo; t < hi; ++t) a[t] = tmp[t];
        return count;
    }

public:
    long long countInversions(vector<int>& nums) {
        vector<int> tmp(nums.size());
        return sortCount(nums, tmp, 0, (int)nums.size());
    }
};

