class Solution {
    public int[][] merge(int[][] intervals) {
        Arrays.sort(intervals, (x, y) -> Integer.compare(x[0], y[0]));
        List<int[]> merged = new ArrayList<>();
        for (int[] cur : intervals) {
            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < cur[0]) {
                merged.add(new int[] {cur[0], cur[1]});
            } else {
                int[] last = merged.get(merged.size() - 1);
                last[1] = Math.max(last[1], cur[1]);
            }
        }
        return merged.toArray(new int[0][]);
    }
}

class Solution {
    public int[] countBits(int n) {
        int[] ans = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            ans[i] = ans[i >> 1] + (i & 1);
        }
        return ans;
    }
}

class Solution {
    public int mySqrt(int x) {
        long lo = 0, hi = x;
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            if (mid * mid <= x) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        return (int) lo;
    }
}

class Solution {
    public String longestPalindrome(String s) {
        int n = s.length();
        int bestStart = 0, bestLen = 0;
        for (int center = 0; center < 2 * n - 1; center++) {
            int left = center / 2;
            int right = left + center % 2;
            while (left >= 0 && right < n && s.charAt(left) == s.charAt(right)) {
                left--;
                right++;
            }
            int len = right - left - 1;
            if (len > bestLen) {
                bestLen = len;
                bestStart = left + 1;
            }
        }
        return s.substring(bestStart, bestStart + bestLen);
    }
}

function ListNode(val, next) {
    this.val = val === undefined ? 0 : val;
    this.next = next === undefined ? null : next;
}

function insertionSortList(head) {
    const dummy = new ListNode(0, null);
    let cur = head;
    while (cur !== null) {
        const next = cur.next;
        let prev = dummy;
        while (prev.next !== null && prev.next.val < cur.val) {
            prev = prev.next;
        }
        cur.next = prev.next;
        prev.next = cur;
        cur = next;
    }
    return dummy.next;
}

function hammingDistance(x, y) {
    const diff = x ^ y;
    let count = 0;
    for (let bit = 0; bit < 32; bit++) {
        count += (diff >>> bit) & 1;
    }
    return count;
}

function successfulPairs(spells, potions, success) {
    const sorted = potions.slice().sort((a, b) => a - b);
    const m = sorted.length;
    const result = new Array(spells.length);
    for (let i = 0; i < spells.length; i++) {
        let lo = 0;
        let hi = m;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (spells[i] * sorted[mid] >= success) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        result[i] = m - lo;
    }
    return result;
}

function countMaxOrSubsets(nums) {
    const n = nums.length;
    let maxOr = 0;
    for (const x of nums) {
        maxOr |= x;
    }
    let count = 0;
    for (let mask = 1; mask < (1 << n); mask++) {
        let cur = 0;
        for (let i = 0; i < n; i++) {
            if ((mask >> i) & 1) {
                cur |= nums[i];
            }
        }
        if (cur === maxOr) {
            count++;
        }
    }
    return count;
}

