func heightChecker(heights []int) int {
    n := len(heights)
    expected := make([]int, n)
    copy(expected, heights)
    for pass := 0; pass < n-1; pass++ {
        swapped := false
        for i := 0; i < n-1-pass; i++ {
            if expected[i] > expected[i+1] {
                expected[i], expected[i+1] = expected[i+1], expected[i]
                swapped = true
            }
        }
        if !swapped {
            break
        }
    }
    mismatches := 0
    for i := 0; i < n; i++ {
        if heights[i] != expected[i] {
            mismatches++
        }
    }
    return mismatches
}

