int longestCommonSubstring(const char *a, int n, const char *b, int m) {
    int *dp = calloc((size_t)(n + 1) * (m + 1), sizeof(int));
    int best = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a[i - 1] == b[j - 1]) {
                int len = dp[(i - 1) * (m + 1) + (j - 1)] + 1;
                dp[i * (m + 1) + j] = len;
                if (len > best) {
                    best = len;
                }
            }
        }
    }
    free(dp);
    return best;
}

