static int windowReaches(const int *nums, int n, int len, int target) {
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += nums[i];
        if (i >= len) {
            sum -= nums[i - len];
        }
        if (i >= len - 1 && sum >= target) {
            return 1;
        }
    }
    return 0;
}

