class Solution {
public:
    int matrixChainOrder(vector<int>& dims) {
        int n = dims.size();
        vector<vector<int>> memo(n, vector<int>(n, -1));
        return solve(dims, 1, n - 1, memo);
    }

private:
    int solve(vector<int>& dims, int i, int j, vector<vector<int>>& memo) {
        if (i >= j) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        int best = INT_MAX;
        for (int k = i; k < j; k++) {
            int cost = solve(dims, i, k, memo) + solve(dims, k + 1, j, memo) +
                       dims[i - 1] * dims[k] * dims[j];
            if (cost < best) best = cost;
        }
        memo[i][j] = best;
        return best;
    }
};

