        if (r >= n || c >= m || grid[r][c] === 1) {
            return 0;
        }
        if (r === n - 1 && c === m - 1) {
            return 1;
        }
        if (memo[r][c] !== -1) {
            return memo[r][c];
        }
        memo[r][c] = count(r + 1, c) + count(r, c + 1);
        return memo[r][c];
    }

    return count(0, 0);
}

