func crossSum(nums []int, lo, mid, hi int) int {
    leftBest, sum := nums[mid], 0
    for i := mid; i >= lo; i-- {
        sum += nums[i]
        if sum > leftBest {
            leftBest = sum
        }
    }
    rightBest := nums[mid+1]
    sum = 0
    for i := mid + 1; i <= hi; i++ {
        sum += nums[i]
        if sum > rightBest {
            rightBest = sum
        }
    }
    return leftBest + rightBest
}

func maxSub(nums []int, lo, hi int) int {
    if lo == hi {
        return nums[lo]
    }
    mid := lo + (hi-lo)/2
    best := maxSub(nums, lo, mid)
    if right := maxSub(nums, mid+1, hi); right > best {
        best = right
    }
    if cross := crossSum(nums, lo, mid, hi); cross > best {
        best = cross
    }
    return best
}

