// ops[i] >= 0 enqueues ops[i]; ops[i] < 0 dequeues and records the front value.
vector<int> simulateQueue(const vector<int>& ops) {
    stack<int> inbox, outbox;
    vector<int> dequeued;
    for (int op : ops) {
        if (op >= 0) {
            inbox.push(op);
            continue;
        }
        if (outbox.empty()) {
            while (!inbox.empty()) {
                outbox.push(inbox.top());
                inbox.pop();
            }
        }
        if (!outbox.empty()) {
            dequeued.push_back(outbox.top());
            outbox.pop();
        }
    }
    return dequeued;
}

class Solution {
    public int findCircleNum(int[][] isConnected) {
        int n = isConnected.length;
        boolean[] visited = new boolean[n];
        int[] stack = new int[n];
        int provinces = 0;
        for (int start = 0; start < n; start++) {
            if (visited[start]) continue;
            provinces++;
            int top = 0;
            stack[top++] = start;
            visited[start] = true;
            while (top > 0) {
                int city = stack[--top];
                for (int other = 0; other < n; other++) {
                    if (isConnected[city][other] == 1 && !visited[other]) {
                        visited[other] = true;
                        stack[top++] = other;
                    }
                }
            }
        }
        return provinces;
    }
}

import java.util.ArrayDeque;
