function countTriangles(adj) {
  const n = adj.length;
  let triangles = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (adj[i][j] !== 1) continue;
      for (let k = j + 1; k < n; k++) {
        if (adj[j][k] === 1 && adj[i][k] === 1) {
          triangles++;
        }
      }
    }
  }
  return triangles;
}

// Each row of mat is sorted (all 0s before all 1s); return the row with the most 1s.
function rowWithMaxOnes(mat) {
  const rows = mat.length;
  const cols = mat[0].length;
  let bestRow = -1;
  let bestCount = 0;
  for (let r = 0; r < rows; r++) {
    let lo = 0;
    let hi = cols;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (mat[r][mid] === 1) hi = mid;
      else lo = mid + 1;
    }
    if (cols - lo > bestCount) {
      bestCount = cols - lo;
      bestRow = r;
    }
  }
  return bestRow;
}

