func pathInZigZagTree(label int) []int {
	depth := 0
	for (1 << depth) <= label {
		depth++
	}
	path := make([]int, depth)
	for depth > 0 {
		path[depth-1] = label
		lo := 1 << (depth - 1)
		hi := (1 << depth) - 1
		label = (lo + hi - label) / 2
		depth--
	}
	return path
}

