type endHeap []int

func (h endHeap) Len() int            { return len(h) }
func (h endHeap) Less(i, j int) bool  { return h[i] < h[j] }
func (h endHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *endHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *endHeap) Pop() interface{} {
	old := *h
	last := old[len(old)-1]
	*h = old[:len(old)-1]
	return last
}

func minMeetingRooms(intervals [][]int) int {
	sort.Slice(intervals, func(a, b int) bool { return intervals[a][0] < intervals[b][0] })
	ends := &endHeap{}
	for _, meeting := range intervals {
		if ends.Len() > 0 && (*ends)[0] <= meeting[0] {
			heap.Pop(ends)
		}
		heap.Push(ends, meeting[1])
	}
	return ends.Len()
}

