static void siftDown(int* a, int root, int end) {
    while (2 * root + 1 < end) {
        int child = 2 * root + 1;
        if (child + 1 < end && a[child + 1] > a[child]) child++;
        if (a[root] >= a[child]) return;
        int tmp = a[root];
        a[root] = a[child];
        a[child] = tmp;
        root = child;
    }
}

void heapSort(int* nums, int numsSize) {
    for (int i = numsSize / 2 - 1; i >= 0; i--) {
        siftDown(nums, i, numsSize);
    }
    for (int end = numsSize - 1; end > 0; end--) {
        int tmp = nums[0];
        nums[0] = nums[end];
        nums[end] = tmp;
        siftDown(nums, 0, end);
    }
}

#define MOD 1000000007LL

static void mul(long long a[2][2], long long b[2][2]) {
    long long c[2][2];
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            c[i][j] = (a[i][0] * b[0][j] + a[i][1] * b[1][j]) % MOD;
        }
    }
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            a[i][j] = c[i][j];
        }
    }
}

int fib(int n) {
    long long result[2][2] = {{1, 0}, {0, 1}};
    long long base[2][2] = {{1, 1}, {1, 0}};
    while (n > 0) {
        if (n & 1) {
            mul(result, base);
        }
        mul(base, base);
        n >>= 1;
    }
    return (int)result[0][1];
}

