int** generateMatrix(int n, int* returnSize, int** returnColumnSizes) {
    int** matrix = malloc(n * sizeof(int*));
    *returnColumnSizes = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        matrix[i] = malloc(n * sizeof(int));
        (*returnColumnSizes)[i] = n;
    }
    *returnSize = n;
    int top = 0, bottom = n - 1, left = 0, right = n - 1, value = 1;
    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; c++) matrix[top][c] = value++;
        top++;
        for (int r = top; r <= bottom; r++) matrix[r][right] = value++;
        right--;
        for (int c = right; c >= left && top <= bottom; c--) matrix[bottom][c] = value++;
        bottom--;
        for (int r = bottom; r >= top && left <= right; r--) matrix[r][left] = value++;
        left++;
    }
    return matrix;
}

static int dfs(int** grid, int rows, int cols, int r, int c) {
    if (r < 0 || c < 0 || r >= rows || c >= cols || grid[r][c] != 1) return 0;
    grid[r][c] = 2;
    int area = 1;
    area += dfs(grid, rows, cols, r + 1, c);
    area += dfs(grid, rows, cols, r - 1, c);
    area += dfs(grid, rows, cols, r, c + 1);
    area += dfs(grid, rows, cols, r, c - 1);
    return area;
}

int maxAreaOfIsland(int** grid, int gridSize, int* gridColSize) {
    if (gridSize == 0) return 0;
    int cols = gridColSize[0];
    int best = 0;
    for (int r = 0; r < gridSize; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 1) {
                int area = dfs(grid, gridSize, cols, r, c);
                if (area > best) best = area;
            }
        }
    }
    return best;
}

#define INF 1000000000

void floydWarshall(int** dist, int n) {
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            if (dist[i][k] >= INF) continue;
            for (int j = 0; j < n; j++) {
                if (dist[k][j] >= INF) continue;
                long long through = (long long)dist[i][k] + dist[k][j];
                if (through < dist[i][j]) dist[i][j] = (int)through;
            }
        }
    }
}
